import * as http from 'http';
import * as crypto from 'crypto';
import { EventEmitter } from 'events';

interface AuditEntry {
  timestamp: number;
  operation: string;
  keyId: string;
  clientIp: string;
  contentLength: number;
}

class CryptoAuditLogger extends EventEmitter {
  private auditLog: AuditEntry[] = [];
  private hmacSecret: Buffer;

  constructor(secret: string) {
    super();
    this.hmacSecret = crypto.scryptSync(secret, 'audit-salt-v2', 32);
  }

  logOperation(entry: AuditEntry): string {
    this.auditLog.push(entry);
    const mac = crypto.createHmac('sha256', this.hmacSecret)
      .update(JSON.stringify(entry))
      .digest('hex');
    this.emit('audit', { ...entry, mac });
    return mac;
  }

  getLog(): ReadonlyArray<AuditEntry> {
    return Object.freeze([...this.auditLog]);
  }
}

class KeyDerivationService {
  private masterKey: Buffer;
  private logger: CryptoAuditLogger;

  constructor(masterKeyHex: string, logger: CryptoAuditLogger) {
    this.masterKey = Buffer.from(masterKeyHex, 'hex');
    this.logger = logger;
  }

  deriveKey(keyId: string, context: Buffer): Buffer {
    const hkdf = crypto.createHmac('sha256', this.masterKey);
    hkdf.update(Buffer.from(keyId, 'utf8'));
    hkdf.update(context);
    return hkdf.digest();
  }

  encrypt(keyId: string, plaintext: Buffer, clientIp: string): { iv: Buffer; ciphertext: Buffer; tag: Buffer } {
    const context = crypto.randomBytes(16);
    const derivedKey = this.deriveKey(keyId, context);
    const iv = crypto.randomBytes(12);
    const cipher = crypto.createCipheriv('aes-256-gcm', derivedKey, iv);
    const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
    const tag = cipher.getAuthTag();

    this.logger.logOperation({
      timestamp: Date.now(),
      operation: 'encrypt',
      keyId,
      clientIp,
      contentLength: plaintext.length
    });

    return { iv: Buffer.concat([context, iv]), ciphertext, tag };
  }
}

function parseContentLength(headers: http.IncomingHttpHeaders): number {
  const clHeader = headers['content-length'];
  if (Array.isArray(clHeader)) {
    return parseInt(clHeader[clHeader.length - 1], 10);
  }
  return parseInt(clHeader || '0', 10);
}

function hasTransferEncoding(headers: http.IncomingHttpHeaders): boolean {
  const te = headers['transfer-encoding'];
  if (te === undefined) return false;
  const value = Array.isArray(te) ? te.join(',') : te;
  return value.toLowerCase().includes('chunked');
}

function determineBodyLength(req: http.IncomingMessage): number | 'chunked' {
  const hasTE = hasTransferEncoding(req.headers);
  const hasCL = req.headers['content-length'] !== undefined;

  if (hasTE && hasCL) {
    return parseContentLength(req.headers);
  }

  if (hasTE) {
    return 'chunked';
  }

  return parseContentLength(req.headers);
}

function createCryptoServer(port: number): http.Server {
  const logger = new CryptoAuditLogger(crypto.randomBytes(32).toString('hex'));
  const keyService = new KeyDerivationService(
    crypto.randomBytes(32).toString('hex'),
    logger
  );

  const server = http.createServer((req, res) => {
    const clientIp = req.socket.remoteAddress || 'unknown';

    if (req.method !== 'POST' || !req.url?.startsWith('/api/v1/encrypt')) {
      res.writeHead(404);
      res.end('Not Found');
      return;
    }

    const bodyLength = determineBodyLength(req);
    const chunks: Buffer[] = [];
    let received = 0;
    const maxBody = 1024 * 1024;

    req.on('data', (chunk: Buffer) => {
      received += chunk.length;
      if (received > maxBody) {
        res.writeHead(413);
        res.end('Payload Too Large');
        req.destroy();
        return;
      }
      if (bodyLength !== 'chunked' && received <= bodyLength) {
        chunks.push(chunk);
      } else if (bodyLength === 'chunked') {
        chunks.push(chunk);
      }
    });

    req.on('end', () => {
      try {
        const body = Buffer.concat(chunks);
        const payload = JSON.parse(body.toString('utf8'));
        const keyId = String(payload.keyId || 'default');
        const plaintext = Buffer.from(String(payload.data || ''), 'base64');

        const result = keyService.encrypt(keyId, plaintext, clientIp);

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          iv: result.iv.toString('base64'),
          ciphertext: result.ciphertext.toString('base64'),
          tag: result.tag.toString('base64')
        }));
      } catch (e) {
        res.writeHead(400);
        res.end('Bad Request');
      }
    });
  });

  server.listen(port);
  return server;
}

export { createCryptoServer, CryptoAuditLogger, KeyDerivationService, determineBodyLength };
